import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = () => {
  const [messages, setMessages] = useState([]);
  const [isLive, setIsLive] = useState(false);
  const [caption, setCaption] = useState("Press here to activate the mic");
  const [inputValue, setInputValue] = useState('');
  const scrollRef = useRef(null);

  const speak = (text, lang = 'en-IN') => {
    const msg = new SpeechSynthesisUtterance(text);
    msg.lang = lang;
    window.speechSynthesis.speak(msg);
  };

  const addMessage = (sender, text) => {
    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setMessages(prev => [...prev, { sender, text, time }]);
  };

  // 1. DYNAMIC LANGUAGE & SERVICE FLOW
  const startSession = () => {
    setIsLive(true);
    addMessage("Voice Web", "Welcome to SkySync. Please select your language.");
    speak("Welcome to Sky Sync. Please select your preferred language.");

    const languages = [
      { msg: "For English, Press 1", lang: "en-GB" },
      { msg: "हिंदी के लिए, दो दबाएं", lang: "hi-IN" },
      { msg: "తెలుగు కోసం, మూడు నొక్కండి", lang: "te-IN" },
      { msg: "മലയാളത്തിന്, నాలుగు అమర్", lang: "ml-IN" },
      { msg: "தமிழுக்கு, ஐந்தை அழு", lang: "ta-IN" },
      { msg: "ಕನ್ನಡಕ್ಕಾಗಿ, ಆರನ್ನು ಒ", lang: "kn-IN" },
      { msg: "বাংলার জন্য, সাত টিপুন", lang: "bn-IN" },
      { msg: "मराठीसाठी, आठ दाबा", lang: "mr-IN" },
      { msg: "ગુજરાતી માટે, નવ દબાવો", lang: "gu-IN" },
      { msg: "ਪੰਜਾਬੀ ਲਈ, ਦਸ ਦਬਾਓ", lang: "pa-IN" }
    ];

    languages.forEach((item, index) => {
      setTimeout(() => {
        setCaption(item.msg);
        speak(item.msg, item.lang);
        if(index === languages.length - 1) {
           setTimeout(() => {
             addMessage("Voice Web", "Language list sent. Waiting for selection...");
             startListening();
           }, 2000);
        }
      }, (index + 1) * 2000);
    });
  };

  const startListening = () => {
    const SpeechRecognition = window.window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.start();
    recognition.onresult = (event) => handleInteraction(event.results[0][0].transcript);
  };

  const handleInteraction = (val) => {
    const input = val.toLowerCase();
    addMessage("You", val);

    if (input.includes("telugu") || input.includes("3") || input.includes("తెలుగు")) {
      speak("తెలుగు ఎంపిక చేయబడింది. దయచేసి మీకు కావలసిన సేవను ఎంచుకోండి: 1. బుకింగ్, 2. రీఫండ్.", "te-IN");
      addMessage("Voice Web", "Telugu Selected. Service List Sent: 1. Flight Booking, 2. Refund Processing.");
    } else if (input.includes("booking") || input.includes("బుకింగ్")) {
      speak("Searching for flights. Where are you flying from?");
      addMessage("Voice Web", "Flight Search Initialized. Please state your origin and destination.");
    } else if (input.includes("pnr")) {
      // Logic for PNR Generation
      const generatedPNR = "AP" + Math.floor(Math.random() * 900000 + 100000);
      addMessage("Voice Web", `Booking Confirmed! Your PNR is: ${generatedPNR}`);
      speak(`Your booking is confirmed. Your PNR is ${generatedPNR.split('').join(' ')}`);
      localStorage.setItem("latestPNR", generatedPNR); // Saved for Main UI
    }
    setInputValue('');
  };

  return (
    <div style={{background: '#f1f5f9', height: '100vh', display: 'flex', flexDirection: 'column', fontFamily: 'Inter, sans-serif'}}>

      {/* STATUS BAR / HEADER */}
      <div style={{background: 'white', padding: '10px 40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #e2e8f0'}}>
        <div style={{display: 'flex', alignItems: 'center', gap: '12px'}}>
           <div style={{background: '#2563eb', color: 'white', width: '35px', height: '35px', display: 'flex', justifyContent: 'center', alignItems: 'center', borderRadius: '8px', fontSize: '18px'}}>✈️</div>
           <div style={{lineHeight: '1.2'}}>
              <b style={{fontSize: '15px', color: '#0f172a'}}>FLIGHT BOOKING</b>
              <div style={{fontSize: '10px', color: '#64748b'}}>VOICE ASSISTANT</div>
           </div>
        </div>
        <div style={{display: 'flex', background: '#f8fafc', padding: '4px', borderRadius: '25px', gap: '5px'}}>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: 'transparent', fontSize: '13px'}}>Voice Call</button>
           <button style={{padding: '6px 20px', borderRadius: '20px', border: 'none', background: '#2563eb', color: 'white', fontSize: '13px'}}>Voice Web</button>
        </div>
        <div style={{display: 'flex', alignItems: 'center', gap: '20px'}}>
           <span style={{fontSize: '18px', color: '#94a3b8', cursor: 'pointer'}}>🔔</span>
           <span style={{fontSize: '18px', color: '#94a3b8', cursor: 'pointer'}}>❓</span>
           <div style={{display: 'flex', alignItems: 'center', gap: '10px'}}>
              <div style={{textAlign: 'right'}}><div style={{fontSize: '9px', color: '#94a3b8'}}>Welcome,</div><b style={{fontSize: '13px'}}>User</b></div>
              <div style={{width: '35px', height: '35px', borderRadius: '50%', background: '#cbd5e1', border: '2px solid white'}}></div>
           </div>
        </div>
      </div>

      <div style={{display: 'grid', gridTemplateColumns: '260px 1fr 280px', gap: '20px', padding: '20px', flex: 1, overflow: 'hidden'}}>

        {/* EXTREME LEFT: FLIGHT SERVICES */}
        <div style={{background: 'white', borderRadius: '20px', padding: '20px', boxShadow: '0 2px 10px rgba(0,0,0,0.02)'}}>
          <h4 style={{fontSize: '14px', marginBottom: '15px'}}>Flight Services</h4>
          {['Flight Booking', 'Booking Management', 'Refund Processing', 'Baggage Status', 'Web Check-In', 'PNR Status Check', 'Seat Selection', 'Flight Status Tracking'].map((s, i) => (
            <div key={i} style={{display: 'flex', alignItems: 'center', padding: '12px', marginBottom: '8px', borderRadius: '12px', fontSize: '12px', background: i===0 ? '#eff6ff' : 'transparent', color: i===0 ? '#2563eb' : '#475569'}}>
               <span style={{marginRight: '10px'}}>📄</span> {s}
            </div>
          ))}
        </div>

        {/* MIDDLE PARTITION: SPLIT INTO MIC & TRANSCRIPT */}
        <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
           {/* Left Half: Mic Area */}
           <div style={{background: 'white', borderRadius: '20px', padding: '30px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', boxShadow: '0 2px 10px rgba(0,0,0,0.02)'}}>
              <div style={{textAlign: 'center', marginBottom: '30px'}}>
                 <h3 style={{margin: 0, fontSize: '18px'}}>Voice Web Assistant</h3>
                 <p style={{color: '#64748b', fontSize: '12px', marginTop: '5px'}}>{caption}</p>
              </div>
              <div onClick={startSession} style={{width: '180px', height: '180px', borderRadius: '50%', background: 'radial-gradient(circle, #2563eb 0%, #1e3a8a 100%)', display: 'flex', justifyContent: 'center', alignItems: 'center', color: 'white', cursor: 'pointer', boxShadow: '0 10px 30px rgba(37, 99, 235, 0.3)'}} className={isLive ? 'pulse-mic' : ''}>
                 <span style={{fontSize: '50px'}}>🎙️</span>
              </div>
              <p style={{marginTop: '20px', color: '#2563eb', fontSize: '13px'}}>● Press here to activate the mic</p>
           </div>

           {/* Right Half: Live Captions / Transcript */}
           <div style={{background: 'white', borderRadius: '20px', padding: '20px', display: 'flex', flexDirection: 'column', boxShadow: '0 2px 10px rgba(0,0,0,0.02)', overflow: 'hidden'}}>
              <div style={{display: 'flex', justifyContent: 'space-between', marginBottom: '15px', paddingBottom: '10px', borderBottom: '1px solid #f1f5f9'}}>
                 <b style={{fontSize: '13px'}}>Live Captions / Transcript</b>
                 <span style={{color: '#10b981', fontSize: '10px', fontWeight: 'bold'}}>● LIVE</span>
              </div>
              <div style={{flex: 1, overflowY: 'auto'}} ref={scrollRef}>
                {messages.map((m, i) => (
                  <div key={i} style={{marginBottom: '12px', background: m.sender === 'You' ? '#eff6ff' : '#f8fafc', padding: '10px', borderRadius: '12px'}}>
                    <div style={{fontSize: '10px', color: '#2563eb', fontWeight: 'bold'}}>{m.sender} said:</div>
                    <div style={{fontSize: '12px', color: '#334155'}}>{m.text}</div>
                  </div>
                ))}
              </div>
           </div>
        </div>

        {/* EXTREME RIGHT: QUICK SUGGESTIONS */}
        <div style={{background: 'white', borderRadius: '20px', padding: '20px', boxShadow: '0 2px 10px rgba(0,0,0,0.02)'}}>
           <h4 style={{fontSize: '14px', marginBottom: '15px'}}>Quick Suggestions</h4>
           <div style={{display: 'grid', gap: '10px'}}>
              {['Track my booking', 'Check baggage status', 'Web check-in', 'PNR status', 'Cancel my flight'].map(q => (
                <div key={q} style={{padding: '10px', border: '1px solid #f1f5f9', borderRadius: '10px', fontSize: '12px', color: '#64748b', display: 'flex', alignItems: 'center', gap: '8px'}}>
                  <span style={{color: '#2563eb'}}>🔗</span> {q}
                </div>
              ))}
           </div>
        </div>
      </div>

      {/* BOTTOM INPUT BAR */}
      <div style={{background: 'white', padding: '15px 40px', borderTop: '1px solid #e2e8f0', display: 'flex', gap: '15px', alignItems: 'center'}}>
        <input 
          type="text" 
          placeholder="Type your message (optional)..." 
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleInteraction(inputValue)}
          style={{flex: 1, padding: '12px 25px', borderRadius: '30px', border: '1px solid #e2e8f0', background: '#f8fafc', outline: 'none', fontSize: '13px'}} 
        />
        <button onClick={() => handleInteraction(inputValue)} style={{background: '#2563eb', color: 'white', border: 'none', width: '40px', height: '40px', borderRadius: '50%', cursor: 'pointer'}}>➤</button>
      </div>

      <style>{`
        .pulse-mic { animation: ripple 1.8s infinite; }
        @keyframes ripple {
          0% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.4); }
          70% { box-shadow: 0 0 0 30px rgba(37, 99, 235, 0); }
          100% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0); }
        }
      `}</style>
    </div>
  );
};

export default VoiceWeb;
